def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    # find blocks of 2
    seen=set(); blocks=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2 and (r,c) not in seen:
                # flood fill
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==2 and (ny,nx) not in seen:
                            stack.append((ny,nx))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                blocks.append((min(rs),max(rs),min(cs),max(cs)))
    dirs={'UL':(-1,-1),'UR':(-1,1),'DL':(1,-1),'DR':(1,1)}
    cw={'UL':'UR','UR':'DR','DR':'DL','DL':'UL'}
    rays=[]
    for r0,r1,c0,c1 in blocks:
        # adjacent diagonal cells just outside block
        adj={'UL':(r0-1,c0-1),'UR':(r0-1,c1+1),'DL':(r1+1,c0-1),'DR':(r1+1,c1+1)}
        for q,(ar,ac) in adj.items():
            if 0<=ar<h and 0<=ac<w and grid[ar][ac] not in (0,2):
                color=grid[ar][ac]
                dq,dx=dirs[cw[q]]
                # ray starts at the rotated adjacent cell, extends to edge
                sr,sc = (r0-1,c1+1) if cw[q]=='UR' else (r0-1,c0-1) if cw[q]=='UL' else (r1+1,c0-1) if cw[q]=='DL' else (r1+1,c1+1)
                cells=[]
                y,x=sr,sc
                while 0<=y<h and 0<=x<w and grid[y][x]!=2:
                    cells.append((y,x)); y+=dq; x+=dx
                rays.append((color,cells,(ar,ac)))
    # erase dots
    for color,cells,orig in rays:
        out[orig[0]][orig[1]]=0
    for color,cells,orig in rays:
        for y,x in cells: out[y][x]=color
    return out

